[package]
name = "psios-scheduler"
version = "0.1.0"
edition = "2021"
license = "MIT"
publish = false

[dependencies]
chrono = { version = "0.4", features = ["serde"] }
jiff = { version = "0.2", default-features = false, features = ["std", "tzdb-bundle-always"] }
serde = { version = "1", features = ["derive"] }

[package]
name = "xelab-plugin-sdk"
version = "0.1.0"
edition = "2021"
license = "MIT"
publish = false

[dependencies]
futures-util = "0.3"
hyper-util = { version = "0.1", features = ["tokio"] }
prost = "0.13"
rustls = { version = "0.23", default-features = false, features = ["ring", "std", "tls12"] }
rustls-pemfile = "2"
tokio = { version = "1", features = ["net", "time"] }
tokio-rustls = { version = "0.26", default-features = false, features = ["ring", "tls12"] }
tokio-stream = { version = "0.1", features = ["net"] }
tonic = { version = "0.12", features = ["tls"] }
tower = { version = "0.5", features = ["util"] }
x509-parser = "0.16"
zeroize = "1"

[build-dependencies]
tonic-build = "0.12"
protoc-bin-vendored = "3"

[dev-dependencies]
rcgen = "0.13"
tempfile = "3"
tokio = { version = "1", features = ["macros", "rt", "sync"] }

{
  "name": "@psios/reuse-shell",
  "private": true,
  "type": "module",
  "scripts": {
    "check": "find src tests -type f \\( -name '*.js' -o -name '*.mjs' \\) -print0 | xargs -0 -n1 node --check",
    "test": "node --test tests/*.mjs"
  }
}

[package]
name = "psios-runtime"
version = "0.1.0"
edition = "2021"
license = "MIT"
publish = false

[dependencies]
libc = "0.2"
psios-common = { path = "../common" }
psios-host-io = { path = "../host-io" }
psios-plugin-contracts = { path = "../plugin-contracts" }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
sha2 = "0.10"
tokio = { version = "1", features = ["fs", "io-util", "process", "time"] }
tracing = "0.1"
uuid = { version = "1", features = ["v4"] }

[dev-dependencies]
tempfile = "3"
tokio = { version = "1", features = ["macros", "rt"] }

[package]
name = "psios-storage"
version = "0.1.0"
edition = "2021"
license = "MIT"
publish = false

[features]
test-fixtures = ["dep:rustls", "dep:tempfile"]

[dependencies]
async-trait = "0.1"
base64 = "0.22"
chrono = "0.4"
futures-util = "0.3"
hmac = "0.12"
libc = "0.2"
psios-host-io = { path = "../host-io" }
quick-xml = { version = "0.38", features = ["serialize"] }
reqwest = { version = "0.12", default-features = false, features = ["rustls-tls", "stream"] }
ring = "0.17"
rustls = { version = "0.23", optional = true, default-features = false, features = ["ring", "std", "tls12"] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
sha2 = "0.10"
tempfile = { version = "3", optional = true }
tokio = { version = "1", features = ["fs", "io-util", "net", "rt-multi-thread", "sync", "time"] }
tracing = "0.1"
url = "2"
uuid = { version = "1", features = ["serde", "v4"] }
zeroize = "1"

[dev-dependencies]
rustls = { version = "0.23", default-features = false, features = ["ring", "std", "tls12"] }
tempfile = "3"
tokio = { version = "1", features = ["macros", "test-util"] }

[package]
name = "xelab-api-client-example"
version = "0.1.0"
edition = "2021"
license = "MIT"
publish = false

[dependencies]
reqwest = { version = "0.12", default-features = false, features = ["rustls-tls"] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"

[dev-dependencies]
rcgen = "0.13"
rustls = { version = "0.23", default-features = false, features = ["ring", "std", "tls12"] }
tokio = { version = "1", features = ["io-util", "macros", "net", "rt-multi-thread", "sync", "time"] }
tokio-rustls = { version = "0.26", default-features = false, features = ["ring", "tls12"] }

[workspace]

